local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'
local KTool = CS.Engine.Lib.KTool


---@type BeginnerActivityConstants
local BeginnerActivityConstants = import("Game.Activity.BeginnerAssemble.BeginnerActivityConstants")
local TabGroupPath = "Game.Behaviours.CommonTabToggleLeft" --"Game.Activity.RegressionActivity.RegressionTabToggleLeft"
--- from: Assets/BundleResources/Prefabs/RegressionNew/BeginnerAssembleMainDialog5010.prefab > name: BeginnerAssembleMainDialog5010
---@class BeginnerAssembleMainDialog
---@field Env                           	BeginnerAssembleMainDialog
---@field controller                    	Engine.UI.UILuaDialog
---@field RewardRoot                    	UnityEngine.RectTransform               	@ 0    
---@field TxtTime                       	UnityEngine.RectTransform               	@ 1    
---@field TabLeftGroup                  	UnityEngine.RectTransform               	@ 2    
local BeginnerAssembleMainDialog = Class("BeginnerAssembleMainDialog")
local CDTimerModule = CS.Engine.Modules.CDTimerModule
local CountDownTime = 2592000 --30 * 86400 30天的秒数

---@type BeginnerUtils
local BeginnerUtils = import('Game.Activity.BeginnerAssemble.BeginnerUtils')

function BeginnerAssembleMainDialog:__init()
	self._toggleData      = {}        --页签是数据
	self._curActivityId   = 0         --当前选择的活动id
	self._activityNodes   = {}
end

function BeginnerAssembleMainDialog:__delete()
	if self.redPointRefresh then
		Events.RemoveListener(Constants.EventNames.REFRESH_NEW_BEGINNER_RED_POINT,self.redPointRefresh)
		self.redPointRefresh = nil
	end
end

function BeginnerAssembleMainDialog:Awake()
	self.redPointRefresh = Events.AddListener(Constants.EventNames.REFRESH_NEW_BEGINNER_RED_POINT, Bind(self, self.RefreshRedPoint))
end

function BeginnerAssembleMainDialog:OnFocus(focus)
	if focus then
		local node = self._activityNodes[tostring(self._selectedIndex)]
		if node and not isNull(node.go) and node.scr then
			if node.scr.RefreshTopGoods then
				node.scr:RefreshTopGoods()
			end
		end
	end
end

function BeginnerAssembleMainDialog:InitToggleData()
	self._toggleData    = {}
	self._selectedIndex = self:GetSelectIndex()
	
	
	local tempData = {}
	local config = BeginnerActivityConstants.Configs
	for i, v in pairs(config) do
		local isOpen = self:IsOpenPage(v)
		if isOpen then
			table.insert(tempData, v)
		end
	end
	
	table.sort(tempData,function(a,b)
		return a.sort < b.sort
	end )
	
	for i, v in ipairs(tempData) do
		local dojo = v
		dojo.type = checkNumber(i)
		local redPointStatus = self:GetRedPointStatus(dojo.type)
		table.insert(self._toggleData, {
			text = v.name,
			iconPath = v.iconPath,
			dojo = dojo,
			redPointStatus = redPointStatus,
			func = function()
				self:RefreshNode(dojo.type)
			end,
		})
	end
	
end

function BeginnerAssembleMainDialog:GetSelectIndex()
	if not isNull(self.controller.Argument.extra) then
		return checkNumber(self.controller.Argument.extra)
	end
	return 1
end

function BeginnerAssembleMainDialog:IsOpenPage(v)
	local dojo = BeginnerUtils.GetBeginnerDojo()
	if dojo[v.timeKey] then
		local curTime = GameUtils.GetServerTime() or os.time()
		local remainTime = dojo[v.timeKey] - curTime
		if remainTime > 0 then
			return true
		end
	end
	return false
end

function BeginnerAssembleMainDialog:GetRedPointStatus(type)
	local redPoint = false
	local type = tostring(type)
	if type == BeginnerActivityConstants.ActivityType.Task then
		redPoint = BeginnerUtils.GetBeginnerMgr():CheckTaskRedPoint()
	elseif type == BeginnerActivityConstants.ActivityType.Boss then
		redPoint = BeginnerUtils.GetBeginnerMgr():CheckBossRedPoint()
	elseif type == BeginnerActivityConstants.ActivityType.Gift then
		redPoint = BeginnerUtils.GetBeginnerMgr():CheckGiftRedPoint()
	elseif type == BeginnerActivityConstants.ActivityType.Welfare then
		redPoint = BeginnerUtils.GetBeginnerMgr():CheckWelfareRedPoint()
	elseif type == BeginnerActivityConstants.ActivityType.Jump then
		redPoint = BeginnerUtils.GetBeginnerMgr():CheckJumpRedPoint()
	elseif type == BeginnerActivityConstants.ActivityType.Achievement then
		redPoint = BeginnerUtils.GetBeginnerMgr():CheckAchievementRedPoint()
	end
	return redPoint
end

function BeginnerAssembleMainDialog:FillSelf()
	---@type CommonTabToggleLeft
	local scr = CfUtils.GetLuaScr(self.TabLeftGroup, TabGroupPath)
	if scr then
		scr:FillToggles(self._toggleData, self._selectedIndex)
		scr:MoeToItemByIndex(self._selectedIndex)
	end
	self:RefreshNode(self._selectedIndex)
end

--刷新节点
function BeginnerAssembleMainDialog:RefreshNode(index)
	if checkNumber(index) == 0 then
		return
	end
	local data = self._toggleData[checkNumber(index)]
	--先注销当前选择的
	if checkNumber(self._selectedIndex) ~= 0 then
		local toggleData = self._toggleData[self._selectedIndex].dojo
		local node = self._activityNodes[tostring(toggleData.type)]
		if node and node.go then
			self:SetCanvasEnabled(node, false)
		end
	end
	self._selectedIndex = index
	self.controller:SetExtraArgument(self._selectedIndex)
	self:ShowActivityNode(data)
end

function BeginnerAssembleMainDialog:ShowActivityNode(data)
	if not data then return end
	-- 还原顶部导航栏
	--ActivityUtils.RefreshNavigatorGoods()
	local dojo = data.dojo
	if self._activityNodes[tostring(dojo.type)]  then
		self:RefreshActivityNode(data)
	else
		self:CreateActivityNode(data)
	end
end

function BeginnerAssembleMainDialog:RefreshActivityNode(data)
	local dojo = data.dojo
	local node = self._activityNodes[tostring(dojo.type)]
	if node and not isNull(node.go) and node.scr then
		self:SetCanvasEnabled(node, true)
		node.scr:Refresh(dojo, self)
		node.scr:RefreshTopGoods()
	end
end

---创建一个活动页面
---@param data table 页面数据
---@param cb function 回调
function BeginnerAssembleMainDialog:CreateActivityNode(data, cb)
	CfUtils.StartCoroutineWithBlocker(function()
		xTry(function()
			local go = nil
			local dojo = data.dojo
			if dojo.prefabPath then
				local path = string.format("%s.prefab", dojo.prefabPath)
				go = GameUtils.LoadBundleAsync(path, self.RewardRoot.gameObject, false)
			else
				go = GameUtils.LoadBundleAsyncById(dojo.prefabId, self.RewardRoot.gameObject, false, true)
			end
			local scr = CfUtils.GetLuaScr(go, dojo.scrPath)
			local node = {
				go = go,
				scr = scr,
			}
			self._activityNodes[tostring(dojo.type)] = node
			self:RefreshActivityNode(data)
			
			if cb then
				cb()
			end
		end)
	end)
end

function BeginnerAssembleMainDialog:OnInitialize()
	local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
		BeginnerUtils.GetBeginnerMgr():RequestHomeDojo(function()
			self:RefreshSelf()
			self:StartTimeDown()
		end)
	end))
	return coWait
end

function BeginnerAssembleMainDialog:SetTimeShow()
	local dojo = BeginnerUtils.GetBeginnerMgr():GetHomeDojo()
	--region 时间
	local startTime =  dojo.startTime
	local closeTime =  dojo.closeTime
	CfUtils.FillText(self.TxtTime, self:GetShowTimeTxt(startTime, closeTime))
end

function BeginnerAssembleMainDialog:GetShowTimeTxt(startTime ,endTime)
	return GameUtils.CheckUTCTimeformat(GameUtils.l10nTimeData("%m/%d", startTime).."-"..GameUtils.l10nTimeData("%m/%d", endTime))
end

---刷新自身
function BeginnerAssembleMainDialog:RefreshSelf()
	--self:SetTimeShow()
	self:InitToggleData()
	self:FillSelf()
end

function BeginnerAssembleMainDialog:OnFinalize()
	local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
		for _, node in pairs(self._activityNodes) do
			if not isNull(node.go) then
				KTool.SafeDelete(node.go.gameObject, true)
			end
		end
		self:RemoveTimer()
		---更新主界面按钮红点
		BeginnerUtils.GetBeginnerMgr():UpdateRegressHomeRedPoint()
		self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
		self:Delete()
		self = nil --lua层的gc需要
	end))
	return coWait
end

function BeginnerAssembleMainDialog:SetCanvasEnabled(node, enabled)
	if isNull(checkTable(node).go) then return end
	
	local canvas = KTool.GetOrAddComponent(node.go, typeof(CS.UnityEngine.Canvas))
	canvas.enabled = enabled
	
	if node.scr and node.scr.SetEnabled then
		node.scr:SetEnabled(enabled)
	end
end

function BeginnerAssembleMainDialog:RefreshRedPoint(index)
	local index = index or self._selectedIndex
	local redPoint = self:GetRedPointStatus(index)
	---@type CommonTabToggleLeft
	local scr = CfUtils.GetLuaScr(self.TabLeftGroup, TabGroupPath)
	if scr then
		scr:FreshTabRedPointByIndex(index - 1, redPoint)
	end
	
	local node = self._activityNodes[tostring(self._selectedIndex)]
	if node and not isNull(node.go) and node.scr then
		if node.scr.RefreshRedPoint then
			node.scr:RefreshRedPoint()
		end
	end
end

function BeginnerAssembleMainDialog:StartTimeDown()
	local dojo = BeginnerUtils.GetBeginnerDojo()
	local isNeedTimeDown = dojo:IsNeedTimeDown()
	self:RemoveTimer()
	if isNeedTimeDown then
		self.timer = CDTimerModule.GetInstance():AddCD(1, function(count, _, _)
			if count > 0 then
				self:RefreshTimeShow()
			else
				self:StartTimeDown()  --重新开始计时器
			end
		end, CountDownTime, true, true)
	end
end

function BeginnerAssembleMainDialog:RemoveTimer()
	if self.Timer then
		CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.Timer)
		self.Timer = nil
	end
end

function BeginnerAssembleMainDialog:RefreshTimeShow()
	for i, node in pairs(self._activityNodes) do
		if node and not isNull(node.go) and node.scr then
			if node.scr.RefreshTimeShow then
				node.scr:RefreshTimeShow()
			end
		end
	end
end

return BeginnerAssembleMainDialog